# Extract (time, n_list) pairs from the text
function parse_logs(logtxt::AbstractString)
    times = Float64[]
    nlists = Vector{Vector{Float64}}()

    for line in eachline(IOBuffer(logtxt))
        if occursin("t * tau =", line)
            if m = match(r"t \* tau\s*=\s*([0-9.+-eE]+)", line)
                push!(times, parse(Float64, m.captures[1]))
            end
        elseif occursin("n_list = Any[", line)
            # grab everything between brackets (can be long; still on one line in your dump)
            if m = match(r"n_list\s*=\s*Any\[(.*)\]", line)
                nums = strip(m.captures[1])
                vals = isempty(nums) ? Float64[] :
                       parse.(Float64, split(nums, ','))
                push!(nlists, vals)
            end
        end
    end
    return times, nlists
end

times, nlists = parse_logs(logs)

@assert length(times) == length(nlists) "Mismatch: found $(length(times)) times but $(length(nlists)) n_lists."

# Plot all curves with per-list x-ranges so different lengths are OK
plt = plot(xlabel="Site index", ylabel="⟨n⟩",
           title="Occupation profiles vs site index (linear scale)",
           legend=:topright)

for (t, n) in zip(times, nlists)
    sites = 1:length(n)
    plot!(plt, sites, n, marker=:o, label="t·τ=$(round(t, digits=2))")
end

# Make the legend less obnoxious if many curves
plot!(plt, legendfont=font(7), size=(950,550))
display(plt)